def comps(g, skip=()):
    R,C=len(g),len(g[0]); seen=[[False]*C for _ in range(R)]; out=[]
    for i in range(R):
        for j in range(C):
            if seen[i][j] or g[i][j] in skip: continue
            col=g[i][j]; q=deque([(i,j)]); seen[i][j]=True; cs=[]
            while q:
                y,x=q.popleft(); cs.append((y,x))
                for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=y+dy,x+dx
                    if 0<=ny<R and 0<=nx<C and not seen[ny][nx] and g[ny][nx]==col:
                        seen[ny][nx]=True; q.append((ny,nx))
            out.append((col,cs))
    return out
def norm(cells, tr):
    m=min(y for y,x in cells),min(x for y,x in cells)
    return tuple(sorted((y-m[0],x-m[1]) for y,x in cells))
def dihedral(cells):
    res=[]
    for tr in [lambda y,x:(y,x),lambda y,x:(y,-x),lambda y,x:(-y,x),lambda y,x:(-y,-x),
               lambda y,x:(x,y),lambda y,x:(x,-y),lambda y,x:(-x,y),lambda y,x:(-x,-y)]:
        res.append(norm([tr(y,x) for y,x in cells],None))
    return min(res)
def shp(cells): return dihedral(cells)

