# Rebuild a unified dataset: for each grid, all dihedral dup groups + singletons + repainted info
def build(grid, bg):
    g=grid; H=len(g); W=len(g[0])
    byc=defaultdict(list)
    seen=set()
    for y in range(H):
        for x in range(W):
            if g[y][x]!=bg and (y,x) not in seen:
                q=deque([(y,x)]); cl=[]
                seen.add((y,x))
                while q:
                    cy,cx=q.popleft(); cl.append((cy,cx))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=cy+dy,cx+dx
                        if 0<=ny<H and 0<=nx<W and g[ny][nx]!=bg and (ny,nx) not in seen:
                            seen.add((ny,nx)); q.append((ny,nx))
                byc[g[y][x]].append(cl)
    objs=[(c,cl) for c,ls in byc.items() for cl in ls]
    # dihedral groups
    d=defaultdict(list)
    for c,cl in objs: d[dihnorm(cl)].append((c,cl))
    groups=[v for v in d.values() if len(v)>1]
    ncomp={c:len(ls) for c,ls in byc.items()}
    sings={c:cl[0] for c,ls in byc.items() if len(ls)==1}
    return objs, groups, ncomp, sings, (H,W)

